(() => {
  'use strict';

  const BASE_ROOMS = [
    { walls: [1, 3], keys: [], exit: 8, optimal: 2 },
    { walls: [7], keys: [0], exit: 2, optimal: 4 },
    { walls: [], keys: [0, 6], exit: 2, optimal: 6 }
  ];
  const DIRS = [[-1, 0], [0, -1], [1, 0], [0, 1]];

  function transformCell(cell, variant) {
    let x = cell % 3;
    let y = Math.floor(cell / 3);
    if (variant & 4) x = 2 - x;
    for (let i = 0; i < (variant & 3); i += 1) {
      const nextX = 2 - y;
      y = x;
      x = nextX;
    }
    return y * 3 + x;
  }

  function roomFor(seed, roomIndex) {
    const base = BASE_ROOMS[roomIndex];
    const variant = (seed >>> (3 * roomIndex)) & 7;
    return {
      walls: base.walls.map((cell) => transformCell(cell, variant)),
      keys: base.keys.map((cell) => transformCell(cell, variant)),
      exit: transformCell(base.exit, variant),
      optimal: base.optimal
    };
  }

  function has(list, cell) {
    return list.indexOf(cell) !== -1;
  }

  function heldDirection(input) {
    if (input.x < 0) return 0;
    if (input.y < 0) return 1;
    if (input.x > 0) return 2;
    if (input.y > 0) return 3;
    return -1;
  }

  function allKeysHeld(state, room) {
    return state.key_mask === ((1 << room.keys.length) - 1);
  }

  function destination(state, room, direction) {
    const x = state.cell % 3 + DIRS[direction][0];
    const y = Math.floor(state.cell / 3) + DIRS[direction][1];
    if (x < 0 || x > 2 || y < 0 || y > 2) return -1;
    const cell = y * 3 + x;
    if (has(room.walls, cell)) return -1;
    if (cell === room.exit && !allKeysHeld(state, room)) return -1;
    return cell;
  }

  function attempt(state, direction) {
    const room = roomFor(state.seed, state.stage - 1);
    const next = destination(state, room, direction);
    state.feedback_token += 1;
    state.feedback_from = state.cell;
    state.feedback_to = next < 0 ? state.cell : next;
    state.feedback_kind = next < 0 ? 'blocked' : 'step';
    if (next < 0) return;

    state.cell = next;
    state.moves += 1;
    state.room_moves += 1;
    state.meaningful_actions += 1;

    const keyIndex = room.keys.indexOf(next);
    if (keyIndex !== -1 && (state.key_mask & (1 << keyIndex)) === 0) {
      state.key_mask |= (1 << keyIndex);
      state.feedback_kind = 'key';
    }

    if (next === room.exit) {
      const points = Math.max(100, 200 - 20 * Math.max(0, state.room_moves - room.optimal));
      state.score += points;
      state.objective_progress += 1;
      state.stage += 1;
      state.cell = 4;
      state.key_mask = 0;
      state.room_moves = 0;
      state.feedback_kind = state.stage === 4 ? 'success' : 'door';
      state.feedback_to = 4;
      if (state.stage === 4) state.outcome = 'success';
    }
  }

  function create(seed) {
    return {
      seed: seed >>> 0,
      tick: 0,
      score: 0,
      stage: 1,
      cell: 4,
      key_mask: 0,
      outcome: 'playing',
      objective_progress: 0,
      meaningful_actions: 0,
      moves: 0,
      room_moves: 0,
      pointer_actions: 0,
      latch: -1,
      feedback_token: 0,
      feedback_from: 4,
      feedback_to: 4,
      feedback_kind: 'none'
    };
  }

  function step(state, input) {
    if (state.outcome !== 'playing') return;
    state.tick += 1;
    let direction = -1;
    const touching = !!(input.action && input.pointer);
    if (touching) {
      direction = Math.max(0, Math.min(3, Math.floor(input.pointer.x * 4)));
      state.pointer_actions += 1;
      state.latch = -1;
      attempt(state, direction);
    } else {
      direction = heldDirection(input);
      if (direction < 0) {
        state.latch = -1;
      } else if (direction !== state.latch) {
        state.latch = direction;
        attempt(state, direction);
      }
    }
    if (state.outcome === 'playing' && state.tick >= 2400) state.outcome = 'failure';
  }

  function legalCount(state) {
    if (state.outcome !== 'playing') return 0;
    const room = roomFor(state.seed, state.stage - 1);
    let count = 0;
    for (let direction = 0; direction < 4; direction += 1) {
      if (destination(state, room, direction) >= 0) count += 1;
    }
    return count;
  }

  function observe(state) {
    return {
      tick: state.tick,
      score: state.score,
      progress: state.tick / 60,
      interactions: state.meaningful_actions,
      entities: 9,
      quality: {
        stage: state.stage,
        complexity: legalCount(state),
        objective_progress: state.objective_progress,
        meaningful_actions: state.meaningful_actions,
        reversible_state_key: state.stage + ':' + state.cell + ':' + state.key_mask + ':' + state.outcome
      }
    };
  }

  function terminal(state) {
    return state.outcome !== 'playing';
  }

  globalThis.KeywakeCore = { create, step, observe, terminal };
})();

(() => {
  'use strict';
  const canvas = document.querySelector('[data-game-canvas]');
  const roomProgress = document.querySelector('[data-product-progress]');
  const roomKeys = document.querySelector('[data-room-keys]');
  const result = document.querySelector('[data-result]');
  const score = document.querySelector('[data-game-score]');
  const best = document.querySelector('[data-best]');
  const status = document.querySelector('[data-game-status]');

  function updateUi(snapshot) {
    const state = snapshot.state;
    const keys = KeywakeArt.keyCount(state);
    roomProgress.textContent = 'ROOMS ' + state.objective_progress + ' / 3';
    roomKeys.textContent = state.stage <= 3 ? 'ROOM ' + state.stage + ' · KEYS ' + keys.held + ' / ' + keys.total : 'ROOMS COMPLETE';
    score.textContent = String(state.score);
    if (Number.isFinite(snapshot.best)) best.textContent = String(snapshot.best);
    if (state.outcome === 'success') {
      result.textContent = 'ALL ROOMS CLEARED · ' + state.score + ' POINTS · ' + state.moves + ' MOVES · ' + (state.score === 600 ? 'Perfect route.' : 'Efficient routes earn more.');
      status.textContent = 'Complete';
    } else if (state.outcome === 'failure') {
      result.textContent = 'TIME UP · ROOMS CLEARED ' + state.objective_progress + ' / 3';
      status.textContent = 'Time expired';
    } else {
      result.textContent = 'Find every brass key before entering the gold hatch.';
      status.textContent = 'Exploring room ' + state.stage;
    }
  }

  const motionQuery = matchMedia('(prefers-reduced-motion: reduce)');
  const onMotion = () => KeywakeArt.setReducedMotion(motionQuery.matches);
  KeywakeArt.setReducedMotion(motionQuery.matches);
  motionQuery.addEventListener('change', onMotion);
  addEventListener('pagehide', (event) => {
    if (!event.persisted) motionQuery.removeEventListener('change', onMotion);
  });

  fetch('./manifest.json')
    .then((response) => response.json())
    .then((metadata) => {
      PlayJoltGameKit.create({
        core: globalThis.KeywakeCore,
        canvas,
        metadata,
        draw(snapshot, size) {
          KeywakeArt.draw(canvas.getContext('2d'), snapshot, size);
          updateUi(snapshot);
        },
        presentation: KeywakeArt.presentation
      });
    })
    .catch((error) => {
      document.querySelector('[data-game-error]').hidden = false;
      document.querySelector('[data-game-error]').textContent = 'Unable to start Keywake: ' + error.message;
    });
})();

(() => {
  'use strict';
  let reduced = false;
  let token = -1;
  let began = 0;
  let lastTick = -1;
  let lastState = null;
  const DURATION = 260;
  const STATIC_DURATION = 410;

  function roomData(state) {
    const base = [
      { walls: [1, 3], keys: [], exit: 8 },
      { walls: [7], keys: [0], exit: 2 },
      { walls: [], keys: [0, 6], exit: 2 }
    ][Math.min(2, Math.max(0, state.stage - 1))];
    const variant = (state.seed >>> (3 * Math.min(2, Math.max(0, state.stage - 1)))) & 7;
    const transform = (cell) => {
      let x = cell % 3;
      let y = Math.floor(cell / 3);
      if (variant & 4) x = 2 - x;
      for (let i = 0; i < (variant & 3); i += 1) {
        const nx = 2 - y;
        y = x;
        x = nx;
      }
      return y * 3 + x;
    };
    return { walls: base.walls.map(transform), keys: base.keys.map(transform), exit: transform(base.exit) };
  }

  function keyCount(state) {
    if (state.stage > 3) return { held: 0, total: 0 };
    const room = roomData(state);
    let held = 0;
    for (let i = 0; i < room.keys.length; i += 1) if (state.key_mask & (1 << i)) held += 1;
    return { held, total: room.keys.length };
  }

  function presentation() {
    const elapsed = performance.now() - began;
    const active = token >= 0 && elapsed < (reduced ? STATIC_DURATION : DURATION);
    return { reduced_motion: reduced, feedback_active: active, static_feedback: !!(reduced && active) };
  }

  function setReducedMotion(value) { reduced = !!value; }
  function cellCenter(cell, left, top, side) {
    return [left + (cell % 3 + 0.5) * side / 3, top + (Math.floor(cell / 3) + 0.5) * side / 3];
  }
  function rounded(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
  }

  function draw(ctx, snapshot, size) {
    const state = snapshot.state;
    const width = size.width;
    const height = size.height;
    const now = performance.now();
    if (state.tick < lastTick || (lastState && state.stage === 1 && state.tick < 3)) {
      token = -1;
      began = now;
    }
    if (state.feedback_token !== token) {
      token = state.feedback_token;
      began = now;
    }
    lastTick = state.tick;
    lastState = state;

    const scale = Math.min(width / 390, height / 350);
    const font = (n) => Math.max(14, Math.round(n * scale));
    ctx.clearRect(0, 0, width, height);
    const bg = ctx.createLinearGradient(0, 0, width, height);
    bg.addColorStop(0, '#17232d'); bg.addColorStop(1, '#0b1016');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);

    const boardSide = Math.min(width * 0.62, height * 0.55, 215 * scale);
    const boardLeft = (width - boardSide) / 2;
    const boardTop = 53 * scale;
    const room = roomData(state);
    ctx.fillStyle = '#a9c8ce'; ctx.font = '700 ' + font(16) + 'px system-ui'; ctx.textAlign = 'center';
    ctx.fillText(state.stage <= 3 ? 'ROOM ' + state.stage : 'KEYWAKE OPEN', width / 2, 25 * scale);
    ctx.fillStyle = '#7d959b'; ctx.font = '600 ' + font(12) + 'px system-ui';
    const kc = keyCount(state);
    ctx.fillText(state.stage <= 3 ? 'BRASS KEYS  ' + kc.held + ' / ' + kc.total : 'ALL THREE HATCHES OPEN', width / 2, 43 * scale);

    rounded(ctx, boardLeft - 8 * scale, boardTop - 8 * scale, boardSide + 16 * scale, boardSide + 16 * scale, 13 * scale);
    ctx.fillStyle = '#22323a'; ctx.fill();
    for (let cell = 0; cell < 9; cell += 1) {
      const x = boardLeft + (cell % 3) * boardSide / 3;
      const y = boardTop + Math.floor(cell / 3) * boardSide / 3;
      const s = boardSide / 3;
      rounded(ctx, x + 3 * scale, y + 3 * scale, s - 6 * scale, s - 6 * scale, 8 * scale);
      ctx.fillStyle = room.walls.indexOf(cell) >= 0 ? '#10171d' : '#38505a'; ctx.fill();
      ctx.strokeStyle = room.walls.indexOf(cell) >= 0 ? '#5b7379' : '#59717a'; ctx.lineWidth = Math.max(1, 1.5 * scale); ctx.stroke();
      if (room.walls.indexOf(cell) >= 0) {
        ctx.strokeStyle = '#789197'; ctx.lineWidth = 3 * scale;
        ctx.beginPath(); ctx.moveTo(x + s * .27, y + s * .27); ctx.lineTo(x + s * .73, y + s * .73); ctx.moveTo(x + s * .73, y + s * .27); ctx.lineTo(x + s * .27, y + s * .73); ctx.stroke();
      }
    }
    if (state.stage <= 3) {
      const [ex, ey] = cellCenter(room.exit, boardLeft, boardTop, boardSide);
      const hatchOpen = kc.held === kc.total;
      ctx.fillStyle = hatchOpen ? '#e4b75d' : '#8a6a2d';
      rounded(ctx, ex - boardSide / 10, ey - boardSide / 8, boardSide / 5, boardSide / 4, 5 * scale); ctx.fill();
      ctx.fillStyle = '#153c3d'; ctx.fillRect(ex - boardSide / 17, ey - boardSide / 15, boardSide / 8.5, boardSide / 6);
      for (let i = 0; i < room.keys.length; i += 1) {
        if (state.key_mask & (1 << i)) continue;
        const [kx, ky] = cellCenter(room.keys[i], boardLeft, boardTop, boardSide);
        ctx.strokeStyle = '#f2cb65'; ctx.lineWidth = 4 * scale;
        ctx.beginPath(); ctx.arc(kx - 7 * scale, ky, 7 * scale, 0, Math.PI * 2); ctx.moveTo(kx, ky); ctx.lineTo(kx + 15 * scale, ky); ctx.moveTo(kx + 10 * scale, ky); ctx.lineTo(kx + 10 * scale, ky + 6 * scale); ctx.stroke();
      }
    }

    const active = token >= 0 && now - began < (reduced ? STATIC_DURATION : DURATION);
    let drawCell = state.cell;
    let interp = 1;
    if (active && !reduced && state.feedback_kind !== 'blocked') interp = Math.min(1, (now - began) / DURATION);
    const from = state.feedback_from;
    const to = state.feedback_to;
    const [fx, fy] = cellCenter(from, boardLeft, boardTop, boardSide);
    const [tx, ty] = cellCenter(to, boardLeft, boardTop, boardSide);
    let px = tx, py = ty;
    if (active && !reduced && state.feedback_kind !== 'blocked') { px = fx + (tx - fx) * interp; py = fy + (ty - fy) * interp; }
    if (active && (reduced || state.feedback_kind === 'blocked')) {
      const [rx, ry] = cellCenter(drawCell, boardLeft, boardTop, boardSide);
      ctx.strokeStyle = state.feedback_kind === 'blocked' ? '#ff8979' : '#d8f5ed'; ctx.lineWidth = 4 * scale;
      ctx.strokeRect(rx - boardSide / 7, ry - boardSide / 7, boardSide * 2 / 7, boardSide * 2 / 7);
    }
    ctx.fillStyle = '#ff7d6e'; ctx.beginPath(); ctx.arc(px, py, boardSide / 8, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffe0c9'; ctx.beginPath(); ctx.arc(px - boardSide / 25, py - boardSide / 30, boardSide / 28, 0, Math.PI * 2); ctx.fill();

    const padY = height * .80; const padH = height * .18;
    const labels = ['LEFT', 'UP', 'RIGHT', 'DOWN'];
    for (let i = 0; i < 4; i += 1) {
      const x = i * width / 4 + 4 * scale; const w = width / 4 - 8 * scale;
      rounded(ctx, x, padY, w, padH, 10 * scale); ctx.fillStyle = '#27404a'; ctx.fill(); ctx.strokeStyle = '#5e8790'; ctx.lineWidth = 1.5 * scale; ctx.stroke();
      ctx.fillStyle = '#e4f0ee'; ctx.textAlign = 'center'; ctx.font = '800 ' + font(13) + 'px system-ui'; ctx.fillText(labels[i], x + w / 2, padY + padH * .58);
    }
  }

  globalThis.KeywakeArt = { draw, presentation, setReducedMotion, keyCount };
})();

(() => {
  'use strict';

  const canvas = document.querySelector('[data-game-canvas]');
  const roomProgress = document.querySelector('[data-product-progress]');
  const roomKeys = document.querySelector('[data-room-keys]');
  const result = document.querySelector('[data-result]');
  const score = document.querySelector('[data-game-score]');
  const best = document.querySelector('[data-best]');
  const status = document.querySelector('[data-game-status]');
  const errorNode = document.querySelector('[data-game-error]');

  function updateUi(snapshot) {
    const state = snapshot.state;
    const keys = globalThis.KeywakeArt.keyCount(state);
    roomProgress.textContent = 'ROOMS ' + state.objective_progress + ' / 3';
    roomKeys.textContent = state.stage <= 3
      ? 'ROOM ' + state.stage + ' · KEYS ' + keys.held + ' / ' + keys.total
      : 'ROOMS COMPLETE';
    score.textContent = String(state.score);
    if (Number.isFinite(snapshot.best)) best.textContent = String(snapshot.best);

    if (state.outcome === 'success') {
      result.textContent = 'ALL ROOMS CLEARED · ' + state.score + ' POINTS · ' + state.moves + ' MOVES · ' + (state.score === 600 ? 'Perfect route.' : 'Efficient routes earn more.');
      status.textContent = 'Complete';
    } else if (state.outcome === 'failure') {
      result.textContent = 'TIME UP · ROOMS CLEARED ' + state.objective_progress + ' / 3';
      status.textContent = 'Time expired';
    } else {
      result.textContent = 'Find every brass key before entering the gold hatch.';
      status.textContent = 'Exploring room ' + state.stage;
    }
  }

  const motionQuery = matchMedia('(prefers-reduced-motion: reduce)');
  const onMotion = () => globalThis.KeywakeArt.setReducedMotion(motionQuery.matches);
  globalThis.KeywakeArt.setReducedMotion(motionQuery.matches);
  motionQuery.addEventListener('change', onMotion);
  addEventListener('pagehide', (event) => {
    if (!event.persisted) motionQuery.removeEventListener('change', onMotion);
  });

  fetch('./manifest.json')
    .then((response) => {
      if (!response.ok) throw new Error('manifest unavailable');
      return response.json();
    })
    .then((metadata) => {
      PlayJoltGameKit.create({
        core: globalThis.KeywakeCore,
        canvas,
        metadata,
        draw(ctx, snapshot, size) {
          globalThis.KeywakeArt.draw(ctx, snapshot, size);
          updateUi(snapshot);
        },
        presentation: globalThis.KeywakeArt.presentation
      });
    })
    .catch((error) => {
      errorNode.hidden = false;
      errorNode.textContent = 'Unable to start Keywake: ' + error.message;
    });
})();

